function watchdog(agentConnections, broadcast, store) {
  setInterval(() => {
    const now = Date.now();
    for (const [id, ts] of lastHeartbeat.entries()) {
      if (now - ts > HEARTBEAT_TIMEOUT_MS) {
        lastHeartbeat.delete(id);
        if (!agentConnections.has(id)) continue;
        store.devices.setOffline(id);
        broadcast("DEVICE_STALE", {
          deviceId: id, lastSeen: ts, staleMs: now - ts,
        });
      }
    }
  }, 15_000);
}

module.exports = { onHeartbeat, watchdog };
